import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div style={{ maxWidth: '1000px', margin: '40px auto', padding: '40px 20px', textAlign: 'center', background: '#fff', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }}>
      <h1 style={{ fontSize: '36px', marginBottom: '15px', color: '#212529' }}>Добро пожаловать в наш Онлайн-Магазин!</h1>
      <p style={{ fontSize: '18px', color: '#6c757d', marginBottom: '30px', lineHeight: '1.5' }}>
        Широкий ассортимент товаров, удобный поиск, честные цены и быстрая публикация. Находите лучшее или продавайте сами!
      </p>
      
      <div style={{ display: 'flex', justifyContent: 'center', gap: '15px' }}>
        <Link 
          to="/catalog" 
          style={{ 
            background: '#007bff', 
            color: '#fff', 
            padding: '12px 24px', 
            borderRadius: '6px', 
            textDecoration: 'none', 
            fontWeight: 'bold',
            fontSize: '16px' 
          }}
        >
          Перейти в каталог
        </Link>
        <Link 
          to="/register" 
          style={{ 
            background: '#28a745', 
            color: '#fff', 
            padding: '12px 24px', 
            borderRadius: '6px', 
            textDecoration: 'none', 
            fontWeight: 'bold',
            fontSize: '16px' 
          }}
        >
          Стать продавцом
        </Link>
      </div>
    </div>
  );
};

export default Home;
